INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 0, 'theory', 'Квиз: что такое операционная система и откуда взялся Юникс');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 0, 'Какие три задачи решает операционная система?', '["Прячет железо за простыми абстракциями, делит ресурсы между программами и защищает их друг от друга","Рисует интерфейс, хранит документы и проверяет орфографию","Компилирует программы, запускает их и удаляет","Ускоряет процессор, охлаждает память и экономит заряд"]', 0, 'Всё остальное — следствия: файлы и процессы — абстракции, планировщик и память — деление ресурсов, режимы процессора — защита.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 1, 'Почему обычная программа не может прочитать сектор диска напрямую?', '["В программе нет нужных библиотек","Диск доступен только по сети","Она работает в обычном режиме процессора, и команды обращения к устройствам разрешены только ядру в привилегированном режиме","Секторы диска зашифрованы при каждом чтении"]', 2, 'Это ограничение железа, а не договорённость: попытка выполнить привилегированную команду вызывает исключение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 2, 'Как обычная программа получает услугу ядра?', '["Прыжком по адресу в памяти ядра","Через системный вызов — единственную проверяемую дверь из обычного режима в режим ядра","Записью в файл конфигурации","Через специальный сетевой порт"]', 1, 'Системный вызов переключает процессор в режим ядра и передаёт управление известному обработчику, где проверяются права и аргументы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 3, 'Почему Юникс удалось перенести на разные компьютеры?', '["Он целиком написан на ассемблере общего процессора","Его запускали только в виртуальных машинах","Он не использовал память","Его переписали на языке C, и при переносе нужно было переработать лишь небольшую машинно-зависимую часть"]', 3, 'В 1973 году Ритчи создал C как раз для системного программирования. Благодаря этому Unix и перестал зависеть от конкретного железа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 4, 'Что такое Linux в строгом смысле слова?', '["Полная операционная система с интерфейсом и программами","Название для всех Unix-систем","Только ядро; вместе с утилитами GNU, библиотеками и пакетами оно образует дистрибутив","Командная оболочка для ядра BSD"]', 2, 'Поэтому «Debian» или «Fedora» — дистрибутивы, а ядро у них одно и то же семейство — Linux.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 5, 'Чем монолитное ядро отличается от микроядра?', '["Подсистемы монолитного ядра работают в одном адресном пространстве в привилегированном режиме; у микроядра большая часть вынесена в обычные процессы","Монолитное ядро не поддерживает модули","Микроядро всегда быстрее монолитного","Монолитное ядро не имеет драйверов"]', 0, 'Linux монолитный, но модульный: драйверы можно подгружать, при этом они выполняются с правами ядра.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 6, 'Что описывает стандарт POSIX?', '["Формат файловой системы ext4","Протокол обмена между ядром и сетевой картой","Устройство процессора x86","Общий интерфейс Unix-подобных систем: системные вызовы, утилиты и поведение оболочки"]', 3, 'Благодаря POSIX программа, написанная для одной системы, с небольшими правками собирается на другой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 7, 'Что означает принцип «всё есть файл»?', '["Все программы хранятся в одном каталоге","Диски, терминалы, каналы и многое другое доступны через одни и те же вызовы open, read и write","Файлы нельзя удалять, пока они открыты","Каждый файл обязан иметь расширение"]', 1, 'Единый интерфейс — главная причина, почему маленькие программы можно соединять в конвейеры.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 1, 'theory', 'Квиз: файловая система, иноды и ссылки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 0, 'Где в Linux хранится имя файла?', '["В иноде рядом с правами и размером","В записи каталога: пара «имя — номер инода»","В первом блоке данных самого файла","В суперблоке файловой системы"]', 1, 'Инод описывает файл без имени. Имя лежит в каталоге, поэтому переименование правит одну строку таблицы и не трогает данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 1, 'Вы удалили огромный лог командой rm, но процесс держит его открытым. Что с местом на диске?', '["Освободится сразу после rm","Освободится только после перезагрузки","Система не даст удалить открытый файл","Оно не освободится, пока процесс не закроет файл: инод жив, пока есть открытый дескриптор"]', 3, 'rm убирает имя, но инод освобождается, когда исчезли и имена, и открытые дескрипторы. Лечится перезапуском программы или закрытием дескриптора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 2, 'Что произойдёт со ссылками после удаления «оригинального» имени файла?', '["Обе продолжат работать","Обе станут битыми","Жёсткая ссылка продолжит работать, а символическая станет битой","Жёсткая станет битой, символическая продолжит работать"]', 2, 'Жёсткая ссылка — ещё одно имя того же инода, данные живы, пока счётчик имён не ноль. Символическая хранит только путь и без цели указывает в пустоту.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 3, 'Команда df -h показывает свободные гигабайты, но создать файл нельзя: «нет места на устройстве». Что проверить?', '["Свободные иноды командой df -i: миллионы мелких файлов могли их исчерпать","Размер журнала файловой системы","Переменную окружения TMPDIR","Права на корневой каталог"]', 0, 'Число инодов задаётся при создании файловой системы. Мелкие файлы могут исчерпать иноды раньше, чем место, и ядро ответит той же ошибкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 4, 'Чем журналирование (ext4, XFS) отличается от копирования при записи (Btrfs)?', '["Журнал хранит копии файлов, а CoW — только имена","CoW работает лишь в оперативной памяти","Разницы нет: это два названия одного механизма","Журнал записывает намерение и правит данные на месте, а CoW пишет новую копию и переключает указатель"]', 3, 'После сбоя журнал повторяется или откатывается; при CoW старая версия остаётся целой, отсюда дешёвые снимки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 5, 'Что делает команда mount /dev/sdb1 /mnt?', '["Копирует все файлы диска в каталог /mnt","Подключает файловую систему устройства к каталогу /mnt: путь через эту точку ведёт уже в неё","Форматирует раздел и создаёт в нём каталог /mnt","Создаёт символическую ссылку на устройство внутри /mnt"]', 1, 'Монтирование не копирует данные. Ядро запоминает точку монтирования, и при поиске пути переходит в корень подключённой файловой системы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 6, 'Что такое каталог /proc?', '["Окно в ядро: файлы создаются на лету и показывают процессы и состояние системы, на диске их нет","Каталог на диске, где лежат временные файлы процессов","Раздел подкачки, который виден как каталог","Архив журналов всех запущенных программ"]', 0, 'Это виртуальная файловая система. Чтение файла вызывает функцию ядра, которая прямо сейчас формирует нужный текст.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 7, 'Почему нельзя сделать жёсткую ссылку на файл в другой файловой системе?', '["У другой файловой системы всегда другие права доступа","Ядро не умеет читать чужие каталоги","Запись каталога хранит номер инода, а он уникален только внутри своей файловой системы","Жёсткие ссылки разрешены только в домашнем каталоге"]', 2, 'Жёсткая ссылка — это ещё одно имя того же инода. Через границу файловых систем номер ничего не значит, поэтому там нужна символическая ссылка с путём.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 2, 'theory', 'Квиз: шелл, конвейеры и скрипты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 0, 'Кто раскрывает *.txt в список файлов, когда вы набираете ls *.txt?', '["Ядро при вызове execve","Программа ls внутри себя","Сам шелл, до запуска программы: ls получает уже готовый список","Стандартная библиотека при открытии файла"]', 2, 'Подстановки — работа шелла. Программа получает массив аргументов, и в нём уже нет звёздочки; ядро в разборе строки не участвует.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 1, 'Какая пара вызовов лежит в основе запуска любой программы в Linux?', '["fork создаёт копию процесса, exec заменяет в копии программу","open и read","socket и connect","mmap и munmap"]', 0, 'Шелл делает fork, ребёнок вызывает exec, родитель ждёт через wait. Между fork и exec шелл успевает подменить дескрипторы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 2, 'Чем отличается cmd > out 2>&1 от cmd 2>&1 > out?', '["Ничем: порядок перенаправлений не важен","Во втором оба потока уходят в файл","В первом ошибки теряются","В первом в файл попадают оба потока, во втором ошибки остаются на терминале"]', 3, '2>&1 копирует то, куда вывод указывает в этот момент. Если сначала скопировать, а потом перенаправить вывод, ошибки останутся на старом месте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 3, 'Что делает ядро, если буфер канала между двумя программами конвейера заполнен?', '["Выбрасывает старые данные","Усыпляет пишущую программу, пока читающая не освободит место","Бесконечно увеличивает буфер","Завершает читающую программу"]', 1, 'Канал — буфер в ядре на несколько десятков килобайт. Блокировка писателя при полном буфере и читателя при пустом согласует скорости без хранения данных на диске.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 4, 'Зачем в скриптах включают set -o pipefail?', '["Чтобы сбой любого звена конвейера делал неудачным весь конвейер","Чтобы конвейер работал быстрее","Чтобы вывод ошибок шёл в файл","Чтобы запретить использовать пустые переменные"]', 0, 'Без pipefail код возврата конвейера — это код последней команды, и сбой в начале легко проглядеть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 5, 'Что делает запись command 2>&1?', '["Копирует вывод команды в файл с именем 1","Запускает команду дважды и склеивает вывод","Направляет стандартный поток ошибок туда же, куда сейчас указывает стандартный вывод","Передаёт результат команды следующей команде в конвейере"]', 2, 'Перенаправление подменяет дескриптор: второй теперь указывает на ту же запись об открытом файле, что и первый. Порядок записи перенаправлений важен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 6, 'Почему во фразе cmd1 | cmd2 вторая команда не ждёт завершения первой?', '["Шелл сначала сохраняет весь вывод первой команды во временный файл","Обе запускаются одновременно и соединены каналом: пока в буфере есть место, писатель работает, а читатель берёт данные по мере появления","Вторая команда сама запускает первую в фоне","Ядро выполняет их по очереди на одном процессоре"]', 1, 'Канал — буфер в ядре. Если он пуст, засыпает читатель, если полон — писатель, поэтому скорость сама подстраивается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 7, 'Что означает код возврата программы, равный нулю?', '["Программа ничего не вывела","Программа была прервана сигналом","Программа завершилась досрочно, не закончив работу","Успех: любое другое значение шелл считает ошибкой, и именно по нему работают if, && и ||"]', 3, 'Код возврата — единственное, что родитель получает о результате. Нуль — успех, и условные операторы шелла проверяют именно его.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 3, 'theory', 'Квиз: права, пользователи и привилегии');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 0, 'У файла права rw-r-----. Вы не владелец, но входите в группу файла. Что вы можете?', '["Читать и писать, как владелец","Ничего: «остальные» не имеют прав","Читать и выполнять","Только читать: сработает набор группы, он первый подходящий"]', 3, 'Ядро выбирает первый подходящий набор: владелец, затем группа, затем остальные. Наборы не складываются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 1, 'Какие права получит новый файл, если umask равен 027 (создание с 666)?', '["750","640: из 666 вычитаются биты маски 027","644","600"]', 1, 'Маска снимает биты: группе запрещена запись (2), остальным — всё (7). Из rw-rw-rw- получается rw-r-----, то есть 640.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 2, 'Что даёт бит setuid на исполняемом файле?', '["При запуске эффективный uid процесса становится равен владельцу файла","Файл можно запускать без права на выполнение","Файл виден всем пользователям","Файл нельзя удалить"]', 0, 'Так passwd пишет в закрытый для всех shadow. Реальный uid остаётся вашим, а такие программы держат под строгим учётом: их ошибка даёт чужие права.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 3, 'Для чего нужен sticky-бит на общем каталоге вроде /tmp?', '["Файлы в каталоге автоматически шифруются","Содержимое каталога хранится только в памяти","Удалить или переименовать файл может только его владелец (или владелец каталога и root)","Файлы нельзя читать другим пользователям"]', 2, 'Без sticky право записи в каталог позволяет удалять чужие имена: удаление — это правка каталога. Sticky это запрещает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 4, 'Что такое capabilities (возможности) в Linux?', '["Список файлов, к которым есть доступ","Власть root разбита на примерно сорок отдельных привилегий, процессу выдают только нужные","Дополнительные группы пользователя","Права на запуск программ в контейнере"]', 1, 'Веб-серверу достаточно привязки к привилегированному порту, а рут не нужен. Контейнеры выбрасывают почти все возможности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 5, 'Права rwxr-x--- записаны в восьмеричном виде как...', '["705","570","755","750"]', 3, 'Для владельца rwx = 4+2+1 = 7, для группы r-x = 4+1 = 5, для остальных --- = 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 6, 'Что даёт право x на каталог?', '["Право запускать каталог как программу","Право удалять каталог целиком","Право входить в каталог и обращаться к записям по имени: без него файлы внутри не открыть, даже зная имя","Право видеть список имён в каталоге"]', 2, 'Список имён — это r, а проход через каталог — x. Поэтому у каталога часто бывает --x: заходить можно, а перечислять нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 7, 'Зачем ядро разделило всемогущество рута на привилегии (capabilities)?', '["Чтобы выдавать процессу только нужное, например право занимать порты ниже 1024, не давая остального","Чтобы рут мог работать без пароля","Чтобы обычные пользователи читали любые файлы","Чтобы ускорить проверку прав на файлы"]', 0, 'Раньше программе, которой нужен один порт, приходилось выдавать полный рут. Привилегии позволяют обойтись одной: CAP_NET_BIND_SERVICE.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 4, 'theory', 'Квиз: процессы и сигналы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 0, 'Что именно копирует fork благодаря copy-on-write?', '["Таблицы страниц; сами страницы копируются лишь при первой записи","Всю память процесса сразу","Только регистры процессора","Ничего: родитель и ребёнок навсегда делят память"]', 0, 'Обе таблицы указывают на одни кадры, помеченные «только чтение». Запись вызывает страничную ошибку, и ядро копирует одну страницу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 1, 'Чем в Linux поток отличается от процесса?', '["Поток запускается только в ядре","Поток не имеет собственного стека","Поток — задача, разделяющая память и другие ресурсы с соседями; создаётся тем же clone","Потоки нельзя планировать на разных ядрах"]', 2, 'Ядро работает с задачами. Флаги clone определяют, что разделяется: без разделения получается процесс, с разделением памяти — поток.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 2, 'Что такое зомби-процесс?', '["Процесс в вечном сне D","Завершившийся процесс, код возврата которого ещё не забрал родитель вызовом wait","Процесс, остановленный сигналом STOP","Процесс без родителя"]', 1, 'От зомби остаётся только запись в таблице процессов. Убить его нельзя, помогает завершение или исправление родителя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 3, 'Кто усыновит процесс, у которого завершился родитель?', '["Он сразу завершается","Процесс-дед и только он","Шелл, из которого его запустили","Ближайший subreaper или процесс с номером 1"]', 3, 'Поэтому у отсоединённых демонов родителем часто оказывается процесс 1, а в контейнерах усыновителем служит init контейнера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 4, 'Какой из этих сигналов нельзя перехватить обработчиком?', '["SIGTERM","SIGINT","SIGKILL (так же, как и SIGSTOP)","SIGHUP"]', 2, 'KILL и STOP выполняет само ядро. Поэтому сначала шлют TERM, чтобы программа успела прибраться, а потом уже KILL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 5, 'Почему fork выполняется быстро даже для процесса с гигабайтами памяти?', '["Копируются только таблицы страниц, а сами страницы остаются общими и копируются при первой записи","Ядро копирует память в фоне, пока родитель работает","Дочерний процесс получает пустую память и загружает всё заново","Память делится на два процесса пополам"]', 0, 'Копирование при записи откладывает дорогую работу: если потомок сразу вызывает exec, копировать почти нечего.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 6, 'Что такое зомби-процесс?', '["Процесс, который завис в ожидании диска","Процесс без родителя, который работает бесконечно","Процесс, который не реагирует на сигнал KILL","Завершившийся процесс, у которого родитель ещё не забрал код возврата вызовом wait: в таблице остаётся запись"]', 3, 'Зомби не потребляет процессор и память, но занимает номер процесса. Убрать его можно, только если родитель вызовет wait или сам завершится.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 7, 'Что именно делает вызов exec?', '["Создаёт новый процесс с новым номером","Заменяет программу в существующем процессе: номер процесса остаётся, а память и код новые","Запускает программу в отдельном потоке того же процесса","Копирует процесс вместе со всей памятью"]', 1, 'Поэтому запуск программы в Unix — это пара fork и exec: сначала копия, потом замена содержимого.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 5, 'theory', 'Квиз: планировщик и EEVDF');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 0, 'Какой алгоритм заменил CFS в ядре начиная с версии 6.6?', '["O(1)-планировщик","EEVDF","Round Robin","BFS/MuQSS"]', 1, 'EEVDF добавляет понятия допуска по лагу и виртуального срока и позволяет просить короткий отрезок для лучшей задержки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 1, 'Две готовые задачи имеют nice 0 (вес 1024) и nice 5 (вес 335). Как они примерно поделят процессор?', '["Поровну","Пять к одному","Один к трём","Примерно три к одному"]', 3, 'Доли пропорциональны весам: 1024 к 335 даёт чуть больше трёх. Каждый шаг nice меняет вес примерно в 1,25 раза.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 2, 'Как EEVDF выбирает следующую задачу?', '["Всегда ту, что дольше всех ждёт","Ту, у которой самый маленький pid","Среди задач с неотрицательным лагом берёт ту, у которой самый ранний виртуальный срок","Случайную из готовых"]', 2, 'Лаг — это положенное минус полученное. Отрицательный лаг означает, что задача взяла лишнее и подождёт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 3, 'Как отзывчивой задаче получить процессор быстрее, не меняя долю времени?', '["Запросить короткий отрезок через sched_setattr: её срок наступит раньше","Поднять приоритет до nice -20","Перейти в класс SCHED_FIFO","Отключить прерывания на ядре"]', 0, 'Короткий отрезок сдвигает виртуальный срок вперёд, но доля времени определяется весом, а он не изменился.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 4, 'Что делает sched_ext?', '["Расширяет ядро драйверами на Rust","Увеличивает число приоритетов реального времени","Переносит планировщик в пользовательский процесс без проверок","Позволяет загрузить планировщик на BPF в работающее ядро; при сбое ядро возвращается к EEVDF"]', 3, 'Программа проходит верификатор, подключается на лету и безопасно откатывается. Класс появился в ядре 6.12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 5, 'Как обычный класс планировщика делит процессор между задачами?', '["Поровну между всеми задачами независимо от nice","Пропорционально весам, которые зависят от значения nice: больше вес — больше доля","Задачи с высоким приоритетом работают, пока не завершатся","В порядке создания, по одной"]', 1, 'Планировщик стремится к справедливости: у каждой задачи есть вес, и накопленное время сравнивается с положенным по весу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 6, 'Что нового принёс EEVDF по сравнению с прежним CFS?', '["Задача может попросить короткий срез и получает более ранний срок, поэтому задержку можно запросить напрямую","Он отключил справедливое деление времени","Он работает только на одном ядре","Он заменил классы реального времени"]', 0, 'У EEVDF выбирается задача с самым ранним сроком среди тех, кто имеет право на процессор. Короткий срез — ранний срок — быстрый отклик.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 7, 'Чем класс SCHED_FIFO отличается от обычного?', '["Задача получает кванты времени поровну с остальными","Задача автоматически понижает свой приоритет","Задача работает, пока сама не заблокируется или не уступит процессор; обычные задачи её не вытеснят","Задача выполняется только в режиме ядра"]', 2, 'Реальное время отдаёт процессор по строгому приоритету. Забытый бесконечный цикл в такой задаче может заморозить машину.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 6, 'theory', 'Квиз: системные вызовы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 0, 'Как обычная программа попадает в ядро?', '["Прямым вызовом функции ядра по известному адресу","Чтением памяти ядра через mmap","Командой syscall: номер вызова в rax, аргументы в регистрах, процессор переходит в режим ядра","Записью номера вызова в файл /dev/kernel"]', 2, 'Единственный законный переход из пользовательского режима вверх — системный вызов; всё остальное вызывает исключение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 1, 'Что вернёт read, если файл закончился?', '["Ноль","-1 с кодом ошибки EOF","Число байт предыдущего вызова","Вызов заблокируется навсегда"]', 0, 'Ноль означает конец файла. Любое число меньше запрошенного — тоже нормально, поэтому чтение обычно идёт в цикле.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 2, 'Для чего нужен vDSO?', '["Для запуска драйверов в пользовательском режиме","Для защиты вызовов от перехвата","Для проверки подписей модулей","Часть частых вызовов, например получение времени, выполняется без перехода в ядро"]', 3, 'Ядро подключает к процессу страницу с кодом и данными времени; чтение остаётся в пользовательском режиме и занимает единицы наносекунд.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 3, 'Что показывает strace -c?', '["Использование памяти программой","Сводку: сколько раз вызывался каждый системный вызов и сколько времени он занял","Список загруженных библиотек","Только вызовы, завершившиеся ошибкой"]', 1, 'Обычный strace печатает каждый вызов с аргументами, а ключ -c собирает итоги — удобно искать тысячи мелких read.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 4, 'В чём главное преимущество io_uring?', '["Два общих кольца запросов и результатов: пачка операций уходит за один вызов или совсем без вызовов","Он заменяет файловую систему","Он включает шифрование ввода-вывода","Он работает только для сетевых сокетов"]', 0, 'Меньше переходов в ядро — выше пропускная способность при тысячах одновременных операций.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 5, 'Что возвращает обёртка libc, если системный вызов завершился ошибкой?', '["Отрицательный код ошибки как есть","Ноль и сообщение в stderr","Значение −1, а причину кладёт в переменную errno","Она завершает программу сигналом"]', 2, 'Ядро возвращает ошибку числом, а обёртка превращает её в привычное «−1 и errno», поэтому errno нужно читать сразу после неудачного вызова.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 6, 'Вызов read(fd, buf, 4096) вернул 100. Что это значит?', '["Произошла ошибка чтения","Прочитано 100 байт: частичное чтение — норма, за остальным нужно вызвать read снова","В файле ровно 100 байт, и он больше не вырастет","Ядро округлило размер запроса"]', 1, 'Число — сколько байт прочитано сейчас. Ноль означает конец файла, а меньше запрошенного — вполне обычный ответ для канала, сокета или терминала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 7, 'Что делает ядро, если программа передала в системный вызов неверный указатель?', '["Читает по этому адресу и сразу падает","Перезагружает систему","Молча подставляет нулевой адрес","Проверяет доступ и возвращает ошибку EFAULT, не доверяя адресу из пользовательской памяти"]', 3, 'Граница вызовов — граница доверия: всё, что пришло из пространства пользователя, ядро проверяет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 7, 'theory', 'Квиз: прерывания, отложенная работа и время');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 0, 'Почему обработчик прерывания делят на верхнюю и нижнюю половины?', '["Верхняя работает в пользовательском режиме","Нижняя выполняется на другом процессоре всегда","Деление нужно только для отладки","Верхняя быстро подтверждает прерывание, а долгая работа откладывается и не задерживает остальные события"]', 3, 'Пока идёт верхняя половина, часть прерываний приглушена. Поэтому в ней делают лишь самое срочное.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 1, 'Что нельзя делать в softirq?', '["Обращаться к памяти","Спать, то есть ждать событие или брать спящую блокировку","Работать на нескольких ядрах","Вызывать планировщик косвенно"]', 1, 'Софтирк выполняется вне контекста процесса, ему нечего усыплять. Если нужен сон — используют очередь работ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 2, 'Что приходит на смену тасклетам в современных ядрах?', '["Нижние половины на очередях работ (BH workqueue), появившиеся в ядре 6.9","Спинлоки","Потоки пользователя","Таймеры hrtimer"]', 0, 'Тасклеты объявлены устаревшими, драйверы постепенно переводят на новый интерфейс с нормальной отменой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 3, 'Куда отдать отложенную работу, которой нужно спать?', '["В тасклет","В верхнюю половину обработчика","В очередь работ: её исполняют потоки kworker в контексте процесса","В отдельный софтирк"]', 2, 'Контекст процесса позволяет спать, выделять память с ожиданием и работать с файлами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 4, 'Что делает режим NO_HZ?', '["Отключает все прерывания в системе","Отключает периодический тик на простаивающих ядрах, экономя энергию","Ускоряет тик до одного гигагерца","Запрещает использование таймеров"]', 1, 'Тик нужен планировщику, но будить простаивающее ядро только ради него расточительно. Точное время берётся из счётчика процессора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 5, 'Почему обработчик аппаратного прерывания должен быть коротким?', '["Потому что у него маленький размер кода","Потому что прерывания нельзя обрабатывать на нескольких ядрах","Потому что устройство отключится по тайм-ауту ровно через миллисекунду","Пока он работает, ядро не может заниматься другими делами на этом процессоре, а спать в нём нельзя, поэтому долгую работу откладывают"]', 3, 'Верхняя половина только подтверждает устройство и ставит остальную работу в отложенное исполнение: софтирки, рабочие очереди, потоковые прерывания.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 6, 'Чем рабочая очередь (workqueue) принципиально отличается от софтирка?', '["Она быстрее, потому что работает в контексте прерывания","Она запускается только раз в секунду","Работа идёт в потоке ядра в контексте процесса, поэтому в ней можно уснуть, например, ожидая диск","Она работает исключительно в пространстве пользователя"]', 2, 'Софтирки не спят. Если отложенной работе нужно ждать или брать мьютекс, её отдают рабочей очереди.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 7, 7, 'Зачем ядру высокоточные таймеры (hrtimer), если есть тики?', '["Они срабатывают в нужный момент с точностью до наносекунд и не привязаны к периоду тика","Они считают календарную дату и время суток","Они заменяют планировщик задач","Они нужны только внутри виртуальных машин"]', 0, 'Тик задаёт грубую сетку времени. Для коротких сроков и плотного планирования нужны таймеры, которые аппаратура включает ровно к нужному моменту.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 8, 'theory', 'Квиз: синхронизация и блокировки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 0, 'Почему counter++ без защиты опасен на нескольких ядрах?', '["Это три действия: прочитать, прибавить, записать; два ядра могут прочитать одно значение и потерять обновление","Процессор не умеет складывать числа параллельно","Переменная может превратиться в строку","Ядро запрещает такую запись"]', 0, 'Потерянное обновление проявляется редко и зависит от тайминга, поэтому защищать общие данные нужно всегда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 1, 'Почему внутри спинлока нельзя спать?', '["Спинлок не поддерживает сон на аппаратном уровне","Сон сбрасывает спинлок","Уснёт держатель, а остальные ядра будут крутиться в цикле впустую; возможна и взаимная блокировка","Это ограничение только для 32-битных систем"]', 2, 'Спинлок для коротких участков. Для долгих и спящих используют мьютекс.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 2, 'Данные трогает и обработчик прерывания, и код процесса. Какую блокировку брать в коде процесса?', '["Обычный мьютекс","Спинлок с отключением прерываний на своём ядре (irqsave)","Никакую: прерывание всё равно короткое","Блокировку чтения rwsem"]', 1, 'Иначе обработчик прервёт держателя на том же ядре и зависнет, ожидая блокировку, которую никто не отпустит.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 3, 'Когда RCU освобождает старую версию структуры?', '["Сразу после публикации нового указателя","При следующей перезагрузке","Когда счётчик ссылок стал равен 100","После периода ожидания, когда все читатели, видевшие её, вышли из критических секций"]', 3, 'Читатели не берут блокировок, поэтому писатель ждёт, пока каждое ядро пройдёт безопасную точку, и только потом освобождает старое.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 4, 'Что делает lockdep?', '["Автоматически снимает зависшие блокировки","Ускоряет захват блокировок","Запоминает порядок захвата блокировок и предупреждает о возможном цикле до реального зависания","Отключает прерывания при взятии мьютекса"]', 2, 'Включается в отладочных сборках. Один неправильный порядок захвата в тестах — и лог ядра покажет цепочку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 5, 'Почему спинлок нельзя держать при вызове функции, которая может уснуть?', '["Другие процессоры будут бесполезно крутиться в ожидании, а владелец может не получить процессор обратно в ближайшее время","Потому что спинлок освобождается автоматически при сне","Потому что спящая функция всегда завершается ошибкой","Потому что ядро запрещает вызывать функции внутри блокировки"]', 0, 'Спинлок рассчитан на очень короткие участки. Тот, кому нужно спать, берёт мьютекс.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 6, 'Как RCU позволяет читателям вообще не блокироваться?', '["Читатели берут быстрый спинлок на чтение","Писатели ждут, пока читателей не останется ни одного","Данные защищаются отключением прерываний","Писатель делает новую копию и подменяет указатель, а старую освобождает только после того, как все текущие читатели закончили"]', 3, 'Читатели видят либо старую, либо новую версию целиком. Цена — отложенное освобождение, но чтение остаётся дешёвым.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 7, 'Как проще всего избежать взаимной блокировки двух мьютексов?', '["Брать мьютексы быстрее остальных потоков","Всегда брать их в одном и том же порядке во всём коде","Удерживать оба как можно дольше","Увеличить число потоков"]', 1, 'Взаимная блокировка возникает, когда один поток берёт A затем B, а другой B затем A. Единый порядок разрывает цикл ожидания.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 9, 'theory', 'Квиз: управление памятью');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 0, 'Что происходит при первом обращении к странице после malloc?', '["Программа завершается с ошибкой сегментации","Возникает страничная ошибка, и ядро выделяет обнулённый кадр","Ядро копирует страницу с диска","Ничего: память выдана при malloc"]', 1, 'malloc выдаёт адреса, а физические кадры появляются лениво — при первом обращении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 1, 'Что делает система двойников?', '["Хранит каждую страницу в двух копиях","Сжимает страницы перед выдачей","Выдаёт память только процессам-близнецам","Выдаёт страницы блоками по степеням двойки: большие блоки делит пополам, а свободных двойников склеивает"]', 3, 'Так ядро быстро находит непрерывные куски нужного размера и борется с фрагментацией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 2, 'Зачем ядру slab-аллокатор (сейчас SLUB)?', '["Чтобы шифровать страницы памяти","Чтобы управлять виртуальными адресами процесса","Он режет страницы на одинаковые ячейки под часто выделяемые мелкие объекты ядра","Чтобы сжимать своп"]', 2, 'Выделение ячейки занимает считанные такты, а статистику показывает slabtop; старые варианты SLAB и SLOB удалены.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 3, 'Чем малая страничная ошибка отличается от большой?', '["Малая обходится без чтения с диска, большая требует его","Малая убивает процесс, большая — нет","Малая бывает только в ядре","Малая происходит при записи, большая — при чтении"]', 0, 'Малая — страница уже в памяти или нужна обнулённая; большая заметно медленнее из-за диска.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 4, 'Что произойдёт при превышении memory.max у контрольной группы?', '["Система перезагрузится","Группе молча дадут больше памяти","Все процессы машины получат SIGKILL","Сработает OOM-killer, но только внутри этой группы"]', 3, 'Лимит локализует беду, а systemd-oomd реагирует на давление памяти раньше, пока машина не задохнулась.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 5, 'Что происходит при первом обращении к странице, которую выдал malloc?', '["Программа получает ошибку «нет памяти»","Страничное нарушение: ядро выбирает физическую страницу, обнуляет её и вписывает в таблицу страниц","Страница заранее была заполнена данными с диска","Ядро копирует страницу из соседнего процесса"]', 1, 'malloc лишь выдаёт диапазон адресов. Физическую память ядро подставляет лениво, при первом обращении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 6, 'Для чего нужна система двойников (buddy)?', '["Выдавать непрерывные блоки страниц размером степень двойки и быстро склеивать освобождённых соседей","Хранить копии страниц на диске","Следить за правами доступа к страницам","Шифровать память процессов"]', 0, 'Блок делится пополам до нужного размера, а при освобождении пара «двойников» склеивается обратно, что борется с фрагментацией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 7, 'Что делает убийца при нехватке памяти (OOM killer)?', '["Сжимает память всех процессов","Перезагружает ядро","Выбирает процесс по оценке и завершает его, чтобы освободить память, когда вытеснять уже нечего","Выгружает процессы на диск, не завершая их"]', 2, 'Это последнее средство. На выбор влияет объём, занимаемый процессом, и настройка oom_score_adj.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 10, 'theory', 'Квиз: VFS, кэш страниц и диски');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 0, 'Когда write() возвращается управление?', '["Только после записи на диск","Только после подтверждения устройства","После копирования данных в кэш страниц, раньше, чем они попадут на диск","Только после следующего fsync"]', 2, 'Страницы помечаются грязными, и потоки обратной записи сбрасывают их позже. Поэтому быстрая запись не означает «данные на диске».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 1, 'Как программе гарантировать, что данные дошли до устройства?', '["Вызвать fsync и дождаться его завершения","Вызвать write дважды","Закрыть файл вызовом close","Отключить кэш страниц командой free"]', 0, 'Журнал файловой системы защищает метаданные, а содержимое файла защищает только fsync.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 2, 'Что хранит dentry в VFS?', '["Данные файла","Таблицу монтирований","Права пользователя","Связь имени с инодом; такие записи кэшируются и ускоряют поиск пути"]', 3, 'Вместе с суперблоком, инодом и открытым файлом это четыре объекта VFS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 3, 'Какой планировщик ввода-вывода обычно выбирают для быстрых NVMe?', '["bfq","none: сортировка на быстрых устройствах только мешает","mq-deadline обязательно","Планировщик не нужен: блочного слоя нет"]', 1, 'mq-deadline и kyber уместны на дисках и особых нагрузках, bfq — на рабочих станциях.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 4, 'Что утверждает правило резервного копирования 3-2-1?', '["Три копии на двух разных носителях, одна из них вне площадки","Три диска в RAID, два зеркала, один резервный","Копия раз в три часа, на двух серверах, хранить год","Три диска в RAID, два контроллера, один источник питания"]', 0, 'RAID переживает поломку диска, но не удаление файла и не шифровальщика, поэтому он не заменяет копию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 5, 'Зачем после write вызывать fsync, если важна сохранность данных?', '["write ничего не записывает, пока не закроешь файл","fsync сжимает файл на диске","write лишь кладёт данные в кэш страниц, а fsync заставляет ядро записать их на устройство","fsync нужен только для каталогов"]', 2, 'Успешный write не гарантирует, что данные пережили бы сбой питания. Надёжность даёт fsync (или флаги O_SYNC).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 6, 'Для чего виртуальная файловая система использует таблицы операций?', '["Это список файлов в каталоге","Это набор указателей на функции конкретной файловой системы: слой вызывает их, не зная, что стоит под ним","Это журнал изменений на диске","Это кэш прав доступа"]', 1, 'Так вызов read одинаково работает с ext4, XFS, tmpfs и /proc: у каждой файловой системы своя таблица функций.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 7, 'Какой планировщик ввода-вывода обычно выбирают для быстрого NVMe-диска с несколькими аппаратными очередями?', '["bfq: он всегда быстрее","Любой, кроме none","Ни один: планировщик нельзя отключить","none: переупорядочивание запросов здесь только добавляет задержку"]', 3, 'Планировщик нужен, чтобы сгладить медленную механику. У быстрых SSD очереди обслуживает само устройство.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 11, 'theory', 'Квиз: сеть, стек и eBPF');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 0, 'Какой маршрут выберет ядро, если подходят несколько строк таблицы?', '["Первый в таблице","Последний в таблице","Тот, у которого меньше номер интерфейса","Тот, у которого самый длинный префикс сети"]', 3, 'Маршрут по умолчанию 0.0.0.0/0 имеет нулевой префикс и работает как запасной вариант.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 1, 'Что возвращает вызов accept серверу?', '["Адрес клиента и ничего больше","Новый дескриптор для соединения с конкретным клиентом","Тот же дескриптор, что и у listen","Порт, выбранный клиентом"]', 1, 'Слушающий сокет остаётся для приёма новых клиентов, а обмен идёт через новый дескриптор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 2, 'Сколько всего адресов в сети с маской /24?', '["256","24","255","65 536"]', 0, 'Для хостов обычно доступно 254: один адрес — сама сеть, другой — широковещательный.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 3, 'Что делает XDP?', '["Шифрует пакеты на сетевой карте","Переписывает таблицу маршрутов","Решает судьбу пакета в драйвере, ещё до создания sk_buff: пропустить, отбросить или перенаправить","Сжимает заголовки TCP"]', 2, 'Это самая ранняя точка, поэтому XDP используют для защиты от атак и балансировщиков нагрузки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 4, 'С чего начинать диагностику, когда «не работает сеть»?', '["С перезагрузки роутера","Идти снизу вверх: канал и адрес, маршрут и шлюз, имя, порт","С переустановки программы","С проверки версии ядра"]', 1, 'Так видно, на каком этаже связь теряется: ip link, ip addr, ip route, resolvectl, ss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 5, 'Как ядро решает, куда отправить пакет?', '["По первой записи в таблице, подходящей по порядку","Всегда отправляет на шлюз по умолчанию","Определяет по имени узла через DNS","По таблице маршрутов: выбирается запись с самым длинным совпадающим префиксом адреса"]', 3, 'Чем длиннее префикс, тем точнее маршрут. Шлюз по умолчанию — запись с нулевой длиной, самая общая.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 6, 'Зачем нужен верификатор при загрузке программы eBPF?', '["Ускорить программу в десять раз","Преобразовать программу в машинный код","Доказать, что программа завершится и не обратится к чужой памяти, прежде чем она попадёт в ядро","Проверить подпись производителя сетевой карты"]', 2, 'Код выполняется внутри ядра, поэтому безопасность проверяется заранее: ограниченные циклы, проверенные границы доступа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 7, 'С чего начинать диагностику, если сеть не работает?', '["Идти снизу вверх: связь и интерфейс, адрес, маршрут, имена и только потом сервис","Сразу проверять DNS: причина почти всегда в нём","Перезагружать систему","Сначала править правила межсетевого экрана"]', 0, 'Каждый уровень зависит от нижележащего. Если нет связи на интерфейсе, нет смысла разбирать маршрутизацию.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 12, 'theory', 'Квиз: загрузка, systemd и пакеты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 0, 'Зачем ядру начальный образ initramfs?', '["В нём лежат модули и скрипты, чтобы найти диск, открыть шифрование, собрать тома и смонтировать настоящий корень","В нём хранятся пользовательские данные","Он заменяет загрузчик","Это резервная копия ядра"]', 0, 'Драйвер диска или шифрование часто оформлены модулями, а загрузить их можно только отсюда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 1, 'Чем в unit-файле Requires отличается от After?', '["Ничем: они взаимозаменяемы","After запускает юнит сам","Requires — зависимость (без юнита не работаем), After — лишь порядок запуска","Requires задаёт только порядок"]', 2, 'Порядок и зависимость задаются отдельно. Независимые юниты systemd запускает параллельно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 2, 'Что такое сокетная активация?', '["Служба запускается при каждом пакете и сразу завершается","systemd сам слушает порт и запускает службу при первом соединении, передавая готовый сокет","Сокеты открываются только вручную","Служба отключает сокеты после запуска"]', 1, 'Пока никто не обращается, службы нет. Ядро копит соединения в очереди сокета, поэтому порядок запуска не важен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 3, 'Для чего нужен лимит StartLimit?', '["Ограничить число одновременных клиентов","Ограничить размер журнала","Ограничить время одного запуска","Остановить цикл бесконечных перезапусков: после серии быстрых падений юнит помечается проваленным"]', 3, 'Статус показывает причину последнего падения и последние строки журнала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 4, 'Как посмотреть ошибки службы nginx за последний час?', '["systemctl log nginx --errors","cat /var/log/nginx | grep hour","journalctl -u nginx -p err --since \"1 hour ago\"","dmesg -u nginx -p err"]', 2, 'Журнал структурирован: фильтровать можно по юниту, уровню важности и времени.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 5, 'Что означает Requires= в юните systemd?', '["Зависимость: без нужного юнита этот не запустится; порядок запуска задаётся отдельно директивой After=","Юнит запускается строго после всех остальных","Юнит перезапускается при любой ошибке","Юнит читает настройки из указанного файла"]', 0, 'Зависимость и порядок — разные вещи. Requires говорит «нужен», After — «после».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 6, 'Что такое сокетная активация?', '["Служба сама открывает сокет при загрузке","Сетевая карта запускает службу аппаратно","Все службы запускаются по одной через сокет","systemd сам открывает порт и запускает службу при первом подключении, передавая ей готовый сокет"]', 3, 'Клиенты могут подключаться, пока служба ещё не готова: соединения ждут в очереди открытого сокета.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 7, 'Зачем при загрузке нужен initramfs?', '["Он хранит пользовательские данные во время работы","Небольшая файловая система в памяти с драйверами, благодаря которой ядро находит и монтирует настоящий корень","Он заменяет загрузчик","Он содержит настройки сети всех служб"]', 1, 'Драйвер диска или шифрования может быть модулем, а лежит он на самом диске. Initramfs разрывает этот круг.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 13, 'theory', 'Квиз: контейнеры');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 0, 'Что такое контейнер с точки зрения ядра Linux?', '["Виртуальная машина с собственным ядром","Обычные процессы в наборе пространств имён и контрольных групп; отдельной сущности «контейнер» в ядре нет","Специальный тип файловой системы","Процесс, запущенный от имени root"]', 1, 'Изоляция строится из namespaces (видимость) и cgroups (потребление) общего ядра хозяина.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 1, 'Какой номер получает первый процесс в новом PID-пространстве?', '["Нулевой","Тот же, что на хозяине","Случайный","Единицу — и он отвечает за усыновление сирот"]', 3, 'На хозяине у этого же процесса другой номер: одна задача — два имени в двух мирах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 2, 'Зачем нужно пользовательское пространство имён?', '["Чтобы пользователи могли входить в систему быстрее","Чтобы шифровать домашние каталоги","Чтобы root внутри контейнера отображался на обычного пользователя на хозяине","Чтобы ограничивать пароли"]', 2, 'Так работают контейнеры без прав root: побег даёт лишь права непривилегированного uid.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 3, 'Что означает cpu.max = «50000 100000» в cgroup v2?', '["Не более 50 мс процессорного времени на каждые 100 мс — половина ядра","Не более 50 000 процессов","Не более 100 000 открытых файлов","Приоритет 50 из 100"]', 0, 'Квота задаётся парой «разрешено, период» в микросекундах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 4, 'Что происходит при изменении файла из нижнего слоя образа в overlayfs?', '["Правится сам нижний слой","Файл удаляется из образа","Контейнер останавливается","Файл сначала копируется в верхний слой для записи (copy-up), и правка идёт уже там"]', 3, 'Благодаря этому сто контейнеров делят слои образа и хранят лишь тонкие записываемые добавки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 5, 'Чем контейнер принципиально отличается от виртуальной машины?', '["У контейнера собственное ядро и эмуляция устройств","Контейнер использует общее ядро хоста, а изоляцию дают пространства имён и cgroups","Контейнер работает только на одном процессоре","Контейнер не может изолировать сеть"]', 1, 'Поэтому контейнеры стартуют за доли секунды и почти не имеют накладных расходов, но уязвимость ядра затрагивает всех.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 6, 'Что ограничивают cgroups, в отличие от пространств имён?', '["Ресурсы: процессор, память, ввод-вывод и число процессов; пространства имён ограничивают то, что процесс видит","Видимость файлов и процессов","Доступ к сети по адресам","Права владельца файлов"]', 0, 'Пространства имён отвечают на вопрос «что видно», контрольные группы — «сколько можно».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 7, 'Почему root внутри контейнера с пространством пользователей не равен root хоста?', '["Внутри контейнера рут не имеет никаких прав","Рут хоста запрещён внутри контейнера","Идентификаторы отображаются: нулевой внутри соответствует обычному непривилегированному снаружи","Ядро хоста игнорирует проверки прав"]', 2, 'Так процесс выглядит администратором для себя и без прав за пределами контейнера.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 14, 'theory', 'Квиз: модули, Rust и наблюдаемость');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 0, 'Что означает пара чисел у файла устройства в /dev?', '["Размер устройства в мегабайтах","Владельца и группу","Старшее число выбирает драйвер, младшее — конкретный экземпляр устройства","Версию драйвера и ядра"]', 2, 'Сами файлы создаёт служба udev по событиям, которые присылает ядро.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 1, 'Чем modprobe лучше insmod?', '["Он учитывает зависимости и сам подгружает нужные модули","Он умеет выгружать любые модули принудительно","Он работает без прав root","Он ускоряет модуль"]', 0, 'Файл зависимостей строится заранее, поэтому modprobe сначала загрузит то, от чего зависит модуль.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 2, 'Каков статус Rust в ядре Linux начиная с версии 7.0?', '["Rust полностью заменил Си","Поддержка Rust удалена","Rust разрешён только для userspace-утилит","Экспериментальная метка снята: Rust — штатная часть ядра, на нём уже есть настоящие драйверы"]', 3, 'Поддержка появилась в 6.1; в 6.18 вошли драйверы Binder и Tyr на Rust.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 3, 'Load average равна 12 на машине с 4 ядрами. Как это понимать?', '["Процессор загружен на 12 процентов","Очередь примерно втрое длиннее возможностей, но причину (процессор, диск) нужно искать в vmstat и PSI","У машины 12 ядер","Это норма для любого сервера"]', 1, 'Нагрузка учитывает и ожидание диска. Показатели давления PSI прямо измеряют простои.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 4, 'Почему программа eBPF безопасно загружать в работающее ядро?', '["Верификатор доказывает, что она завершится и не выйдет за пределы памяти","Она работает только в пользовательском режиме без доступа к ядру","Её проверяет антивирус","Она выполняется в отдельной виртуальной машине"]', 0, 'Благодаря этому bpftrace, XDP и sched_ext можно подключать на лету.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 5, 'Что показывает средняя нагрузка (load average)?', '["Процент занятости процессора","Температуру процессора","Среднее число задач, готовых к выполнению или ждущих диска, за 1, 5 и 15 минут","Число запущенных процессов"]', 2, 'Нагрузка выше числа ядер говорит о очереди. Но причина может быть и в диске, а не в процессоре.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 6, 'Как изменить параметр ядра без перезагрузки?', '["Пересобрать ядро","Записать значение в файл под /proc/sys или выполнить sysctl","Отредактировать загрузчик и перезагрузиться","Это невозможно"]', 1, 'Многие параметры живые: запись в файл меняет поведение ядра сразу. Чтобы изменение пережило перезагрузку, его записывают в конфигурацию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 7, 'Чем modprobe удобнее insmod?', '["Он загружает только модули, подписанные производителем","Он выгружает все модули","Он компилирует модуль перед загрузкой","Он находит модуль по имени и сам загружает нужные ему зависимости"]', 3, 'insmod загружает один указанный файл. modprobe читает карту зависимостей модулей.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 15, 'theory', 'Квиз: каналы, общая память и сокеты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 0, 'Что получит читатель канала, когда закрыты все дескрипторы записи?', '["Ошибку EPIPE","Сигнал SIGPIPE","Он будет ждать вечно","Конец файла: read вернёт 0"]', 3, 'Нуль байт — признак конца потока. Именно поэтому важно закрывать неиспользуемые концы канала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 1, 'Что получит писатель, если у канала нет ни одного читателя?', '["Данные уйдут на диск","Сигнал SIGPIPE, а если его игнорировать — ошибку EPIPE","Запись будет ждать читателя вечно","Ядро молча отбросит данные"]', 1, 'Так конвейер завершается, когда следующая программа закончила читать: head останавливает yes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 2, 'Чем именованный канал (FIFO) отличается от анонимного?', '["У него есть имя в файловой системе, поэтому он связывает неродственные процессы","Он хранит данные на диске","Он работает только в обе стороны","Он быстрее, потому что не использует ядро"]', 0, 'Устройство одинаковое: буфер в ядре. Но анонимный канал передаётся только через наследование дескрипторов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 3, 'Что умеет сокет домена Unix, чего не умеет обычный канал?', '["Передавать данные между разными компьютерами","Хранить сообщения после перезагрузки","Передавать открытые файловые дескрипторы и сообщать данные подключившегося процесса","Работать без ядра"]', 2, 'Передача дескриптора идёт через сообщение SCM_RIGHTS, а данные о собеседнике — через SO_PEERCRED.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 4, 'Почему общая память быстрее каналов?', '["Ядро сжимает данные","Данные не копируются через ядро: обе стороны видят одну и ту же физическую страницу","Память лежит на более быстром диске","Общая память не использует таблицы страниц"]', 1, 'Цена скорости — ручная синхронизация: порядок доступа ядро не контролирует.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 5, 'Что делает фьютекс, когда блокировка свободна?', '["Вызывает ядро, чтобы записать владельца","Блокирует все остальные потоки","Отключает прерывания","Берёт её атомарной операцией в пространстве пользователя без системного вызова"]', 3, 'Ядро подключается только при конкуренции: чтобы усыпить ждущего и разбудить его при освобождении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 6, 'Почему в обработчике сигнала нельзя вызывать printf?', '["printf запрещён стандартом на всех этапах работы","Обработчик работает в режиме ядра","Обработчик прерывает программу в любой точке, а printf не рассчитан на повторный вход; разрешены только безопасные для сигналов функции","printf работает слишком медленно"]', 2, 'Если сигнал прервал malloc или printf, повторный вход в них может испортить внутреннее состояние. Безопасно, например, записать байт в канал.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 7, 'Какой способ связи подходит, чтобы передать соседнему процессу открытый файловый дескриптор?', '["Сокет домена Unix: сообщение с SCM_RIGHTS","Анонимный канал","Общая память","Сигнал SIGUSR1"]', 0, 'Получатель получит новый дескриптор на ту же запись об открытом файле, как будто сам вызвал dup.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 16, 'theory', 'Квиз: неблокирующий ввод-вывод, epoll, io_uring и терминалы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 0, 'Что означает ошибка EAGAIN при чтении из неблокирующего дескриптора?', '["Данных пока нет, вызов нужно повторить позже: это не сбой","Дескриптор закрыт","Недостаточно прав","Буфер слишком мал"]', 0, 'Неблокирующий режим возвращает управление сразу. EAGAIN (или EWOULDBLOCK) — обычный ответ «приходи позже».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 1, 'Почему select считают устаревшим для тысяч соединений?', '["Он не умеет ждать сокеты","Он блокирует все сигналы","Он ограничен номерами до 1024, получает маску заново при каждом вызове и просматривает все дескрипторы","Он работает только на файлах"]', 2, 'poll снимает лимит номеров, но тоже копирует и просматривает весь список.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 2, 'Чем epoll выгоднее poll при 10 000 соединений, из которых активны два?', '["epoll работает без ядра","Интересы хранятся в ядре, а epoll_wait возвращает только готовых: цена зависит от числа событий","epoll использует несколько потоков по умолчанию","epoll не поддерживает сокеты"]', 1, 'poll заново обходит всё. У epoll готовые дескрипторы попадают в отдельный список, поэтому ожидание не зависит от числа тихих соединений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 3, 'Что нужно делать в режиме EPOLLET после уведомления?', '["Читать ровно один раз","Закрыть дескриптор","Перерегистрировать дескриптор вызовом epoll_ctl","Читать до EAGAIN, иначе остаток не вызовет нового уведомления"]', 3, 'Режим по фронту сообщает о смене состояния. Недочитанные данные остаются в буфере, но новых уведомлений не будет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 4, 'Почему epoll не помогает при чтении обычного файла на диске?', '["Файлы не поддерживают описатели","epoll работает только по сети","Файл на диске всегда считается «готовым», а read всё равно может ждать диск","Файлы читаются мгновенно из кэша всегда"]', 2, 'Поэтому серверы выносят дисковые операции в пул потоков или используют асинхронные интерфейсы вроде io_uring.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 5, 'Что даёт io_uring?', '["Два кольца в общей памяти: много операций одним системным вызовом, а в режиме опроса — вообще без вызовов","Замену файловой системы","Шифрование сетевого трафика","Запуск программ без процесса"]', 0, 'Программа складывает запросы в кольцо отправки, ядро кладёт результаты в кольцо завершения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 6, 'Что происходит при нажатии Ctrl-C в терминале?', '["Шелл завершается всегда","Ядро перезапускает терминал","Программа получает символ с кодом 3 и сама решает","Драйвер терминала (линейная дисциплина) посылает SIGINT группе процессов переднего плана"]', 3, 'В каноническом режиме терминал сам превращает управляющие символы в сигналы. В сыром режиме символ получит программа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 7, 'Для чего нужен псевдотерминал (pty)?', '["Для шифрования ввода с клавиатуры","Пара master и slave: эмулятор терминала или sshd управляют программой, которая считает, что говорит с настоящим терминалом","Для разделения экрана между пользователями","Для запуска программ без шелла"]', 1, 'Slave выглядит как обычный терминал, а master держит эмулятор, ssh-сервер или tmux.');
